CREATE TABLE PERIODS(
PERIOD_ID		INT PRIMARY KEY IDENTITY(1, 1),
PERIOD_YEAR		INT NOT NULL,
PERIOD_QUARTER  VARCHAR(2) NOT NULL,
PERIOD_LABEL	VARCHAR(10) NOT NULL UNIQUE
);


CREATE TABLE SECTORS(
SECTOR_ID	INT PRIMARY KEY IDENTITY(1, 1),
SECTOR_NAME NVARCHAR(255) NOT NULL UNIQUE
);


CREATE TABLE EMPLOYMENT_EXPECTATIONS(
EXPECTATION_ID					INT PRIMARY KEY IDENTITY(1,1),
PERIOD_ID						INT NOT NULL,
SECTOR_ID						INT NOT NULL,
MAINTAIN_OR_INCREASE_PCT		DECIMAL(5,2) NOT NULL,
DECREASE_PCT					DECIMAL(5,2) NOT NULL,
NO_OPINION_PCT					DECIMAL(5,2) NOT NULL,
CONSTRAINT fk_employment_period
	FOREIGN KEY (PERIOD_ID) REFERENCES PERIODS(PERIOD_ID),
CONSTRAINT fk_employment_sector
	FOREIGN KEY (SECTOR_ID) REFERENCES SECTORS(SECTOR_ID),
CONSTRAINT fk_employment_period_sector
        UNIQUE (PERIOD_ID, SECTOR_ID)
);






CREATE TABLE QUARTERLY_CORE_METRICS(
CORE_METRIC_ID         INT PRIMARY KEY IDENTITY(1,1),
PERIOD_ID               INT NOT NULL,
SECTOR_ID               INT NOT NULL,
EMPLOYEE_COUNT          INT NOT NULL,
OPEN_JOB_COUNT			INT NOT NULL,
OPEN_JOB_RATE_PCT		DECIMAL(5,2) NOT NULL,
OPEN_POSITION_PCT	DECIMAL(5,2) NOT NULL,
CONSTRAINT fk_quarterly_period
	FOREIGN KEY (PERIOD_ID) REFERENCES PERIODS(PERIOD_ID),
CONSTRAINT fk_quarterly_sector
	FOREIGN KEY (SECTOR_ID) REFERENCES SECTORS(SECTOR_ID),
CONSTRAINT pk_quarter_period_sector
        UNIQUE (PERIOD_ID, SECTOR_ID)
);






CREATE TABLE PRODUCTION_EXPECTATIONS(
PRODUCTION_EXPECTATION_ID		  INT PRIMARY KEY IDENTITY(1,1),
PERIOD_ID						  INT NOT NULL,
SECTOR_ID						  INT NOT NULL,
MAINTAIN_OR_INCREASE_PCT		  DECIMAL(5,2) NOT NULL,
DECREASE_PCT					  DECIMAL(5,2) NOT NULL,
NO_OPINION_PCT					  DECIMAL(5,2) NOT NULL,
CONSTRAINT fk_production_period
	FOREIGN KEY (PERIOD_ID) REFERENCES PERIODS(PERIOD_ID),
CONSTRAINT fk_production_sector
	FOREIGN KEY (SECTOR_ID) REFERENCES SECTORS(SECTOR_ID),
CONSTRAINT fk_production_period_sector
        UNIQUE (PERIOD_ID, SECTOR_ID)
);






CREATE TABLE OCCUPATION_SKILL_ANALYSIS(
SKILL_ANALYSIS_ID			 INT PRIMARY KEY IDENTITY(1,1),
PERIOD_ID					 INT NOT NULL, 
OCCUPATION_GROUP			 NVARCHAR(255) NOT NULL,
INDIVIDUAL_SKILL			 INT NOT NULL,
COMMUNICATION_SKILL			 INT NOT NULL,
PROBLEM_SOLVING_SKILL		 INT NOT NULL,
SOCIAL_SKILL				 INT NOT NULL,
TECHNICAL_SKILL				 INT NOT NULL,
CONSTRAINT fk_occupation_skill_period
	FOREIGN KEY (PERIOD_ID) REFERENCES PERIODS(PERIOD_ID)
);


